final class MetalFighterV5View extends BaseArcadeView {
  static final class Shot{float x,y,vx,life;boolean enemy;int power;Shot(float x,float y,float vx,boolean enemy,int power){this.x=x;this.y=y;this.vx=vx;this.enemy=enemy;this.power=power;life=2.4f;}}
  private final ArcadeFx fx=new ArcadeFx();private final Random rnd=new Random(7301L);private final List<Shot> shots=new ArrayList<Shot>();
  private float x=205,ex=748,vx,evx,y,ey,vy,evy,ai,atk,eAtk,specialCd,hitFlash,shake,roundClock=65,comboTimer,special=35,hitStop,intro=1.6f,koTimer,enemyBlock,guard=100,eGuard=100,stun,eStun;
  private int hp=100,ehp=100,score,round=1,pWins,eWins,combo,pAttack,eAttack,facing=1,eFacing=-1,ladder,matchWins;
  private boolean left,right,block,punch,kick,arc,jump,jumpLatch,ground=true,eGround=true;
  private final RectF bL=new RectF(18,432,108,524),bR=new RectF(114,432,204,524),bJ=new RectF(210,432,310,524),bP=new RectF(560,426,654,524),bK=new RectF(660,426,754,524),bB=new RectF(760,426,854,524),bA=new RectF(860,420,958,524);
  MetalFighterV5View(Context c,GateCraftGame o){super(c,o);}
  @Override public int score(){return score;}@Override public int level(){return ladder+1;}@Override public int lives(){return Math.max(1,3-eWins);}@Override public void shutdown(){super.shutdown();fx.clear();shots.clear();}
  @Override public void restart(){x=205;ex=748;y=ey=0;vy=evy=0;hp=ehp=100;vx=evx=0;specialCd=hitFlash=shake=atk=eAtk=hitStop=koTimer=enemyBlock=stun=eStun=0;left=right=block=punch=kick=arc=jump=false;ground=eGround=true;roundClock=65;combo=0;comboTimer=0;guard=eGuard=100;special=Math.max(20,special);intro=1.45f;shots.clear();invalidate();}
  private int foeStyle(){return ladder%5;}
  private String foeName(){String[]a={"KÓKLER KONTÁR","SAROKCSISZOLÓ","DARUKEZELŐ","PLAZMA PALI","MESTERHEGESZTŐ"};return a[foeStyle()];}
  private int foeCol(){int[]c={Color.rgb(152,53,42),Color.rgb(185,95,32),Color.rgb(93,102,116),Color.rgb(117,61,164),Color.rgb(129,36,34)};return c[foeStyle()];}

  @Override void updateGame(float dt){
    fx.update(dt);if(hitStop>0){hitStop-=dt;return;}intro=Math.max(0,intro-dt);if(intro>0)return;specialCd=Math.max(0,specialCd-dt);hitFlash=Math.max(0,hitFlash-dt);shake=Math.max(0,shake-dt);atk=Math.max(0,atk-dt);eAtk=Math.max(0,eAtk-dt);comboTimer=Math.max(0,comboTimer-dt);if(comboTimer<=0)combo=0;roundClock=Math.max(0,roundClock-dt);special=Math.min(100,special+dt*3.7f);stun=Math.max(0,stun-dt);eStun=Math.max(0,eStun-dt);if(!block)guard=Math.min(100,guard+dt*11);if(enemyBlock<=0)eGuard=Math.min(100,eGuard+dt*9);enemyBlock=Math.max(0,enemyBlock-dt);
    float sp=315;if(stun<=0){if(left)vx=-sp;else if(right)vx=sp;else vx*=Math.pow(.0008,dt);if(jump&&!jumpLatch&&ground){vy=-570;ground=false;jumpLatch=true;fx.dust(x,385,8,Color.rgb(92,88,82));}}if(!jump)jumpLatch=false;if(!ground){vy+=1360*dt;y+=vy*dt;if(y>=0){y=0;vy=0;ground=true;fx.dust(x,388,8,Color.rgb(98,93,84));}}x+=vx*dt;x=Math.max(62,Math.min(898,x));facing=x<=ex?1:-1;eFacing=-facing;
    updateEnemyAi(dt);updateShots(dt);
    if(Math.abs(x-ex)<74&&Math.abs(y-ey)<65){float mid=(x+ex)/2;if(x<ex){x=Math.min(x,mid-38);ex=Math.max(ex,mid+38);}else{x=Math.max(x,mid+38);ex=Math.min(ex,mid-38);}}
    if(stun<=0){if(punch){punch=false;strike(10,105,1,.23f);}if(kick){kick=false;strike(16,132,2,.34f);}if(arc){arc=false;if(specialCd<=0&&special>=50){if(special>=99){special=0;specialCd=3.2f;superArc();}else{special-=50;specialCd=2.1f;shots.add(new Shot(x+facing*48,303+y,facing*520,false,22));atk=.42f;pAttack=3;fx.sparks(x+facing*55,303+y,20,Color.rgb(98,202,255));tone(24,50);}}}}
    if(roundClock<=0){if(hp>=ehp)ehp=0;else hp=0;}if(ehp<=0&&koTimer<=0){koTimer=1.35f;pWins++;score+=700+Math.max(0,(int)roundClock)*8;owner.reportScore(score);}if(hp<=0&&koTimer<=0){koTimer=1.35f;eWins++;score=Math.max(0,score-150);owner.reportScore(score);}if(koTimer>0){koTimer-=dt;if(koTimer<=0)nextRoundOrMatch();}
  }
  private void updateEnemyAi(float dt){if(eStun>0)return;int style=foeStyle();ai-=dt;float d=x-ex,ad=Math.abs(d);if(ai<=0){ai=style==1?.10f:.15f+rnd.nextFloat()*.18f;if(style==0){if(ad>150)evx=(d>0?1:-1)*210;else chooseEnemyMove(.48f,.68f);}else if(style==1){if(ad>115)evx=(d>0?1:-1)*300;else chooseEnemyMove(.60f,.77f);}else if(style==2){if(ad>135)evx=(d>0?1:-1)*150;else chooseEnemyMove(.42f,.70f);}else if(style==3){if(ad<190)evx=(d>0?-1:1)*220;else if(rnd.nextFloat()<.52f)enemyProjectile();else evx=(d>0?1:-1)*125;}else{if(ad>145)evx=(d>0?1:-1)*235;else chooseEnemyMove(.55f,.80f);if(rnd.nextFloat()<.12f)enemyProjectile();}}
    if(!eGround){evy+=1360*dt;ey+=evy*dt;if(ey>=0){ey=0;evy=0;eGround=true;}}ex+=evx*dt;ex=Math.max(62,Math.min(898,ex));evx*=Math.pow(.045,dt);
  }
  private void chooseEnemyMove(float attackChance,float blockThreshold){float r=rnd.nextFloat();if(r<attackChance)enemyStrike(rnd.nextFloat()<.35f?2:1);else if(r<blockThreshold)enemyBlock=.42f;else if(r<blockThreshold+.10f&&eGround){evy=-505;eGround=false;}else evx=(x<ex?1:-1)*120;}
  private void enemyProjectile(){if(eAtk>0)return;eAtk=.45f;eAttack=3;shots.add(new Shot(ex+eFacing*45,303+ey,eFacing*420,true,foeStyle()==4?20:15));fx.sparks(ex+eFacing*50,303+ey,15,Color.rgb(190,110,255));}
  private void updateShots(float dt){Iterator<Shot>it=shots.iterator();while(it.hasNext()){Shot s=it.next();s.life-=dt;s.x+=s.vx*dt;if(s.life<=0||s.x<20||s.x>940){it.remove();continue;}if(s.enemy){if(Math.abs(s.x-x)<28&&Math.abs(s.y-(312+y))<60){it.remove();receiveHit(s.power,18);}}else{if(Math.abs(s.x-ex)<30&&Math.abs(s.y-(312+ey))<60){it.remove();enemyReceiveHit(s.power,25);}}}}
  private void strike(int dmg,float range,int kind,float duration){if(atk>0)return;pAttack=kind;atk=duration;if(Math.abs(x-ex)<=range&&Math.abs(y-ey)<82){if(kind==1&&Math.abs(x-ex)<52&&enemyBlock<=0&&rnd.nextFloat()<.24f){enemyReceiveHit(18,38);ex+=facing*48;combo+=2;score+=180;return;}int dealt=dmg+(combo>=2?3:0)+(y<0?3:0);enemyReceiveHit(dealt,kind==2?28:18);}}
  private void enemyReceiveHit(int dmg,float push){int dealt=dmg;if(enemyBlock>0){dealt=Math.max(2,dmg/4);eGuard-=dmg*1.35f;if(eGuard<=0){enemyBlock=0;eStun=1.0f;eGuard=45;fx.sparks(ex,302+ey,24,Color.rgb(255,227,100));}}ehp-=dealt;ex+=facing*push;hitFlash=.10f;shake=dmg>20?.18f:.08f;hitStop=dmg>20?.065f:.035f;combo++;comboTimer=.92f;special=Math.min(100,special+8);score+=dealt*(5+combo);owner.reportScore(score);fx.sparks(ex-facing*22,316+ey,dmg>20?24:11,dmg>20?Color.rgb(105,205,255):Color.rgb(255,192,70));}
  private void enemyStrike(int kind){if(eAtk>0)return;eAttack=kind;eAtk=kind==2?.38f:.27f;if(Math.abs(x-ex)<(kind==2?132:106)&&Math.abs(y-ey)<82){int base=kind==2?17:12;if(foeStyle()==2)base+=5;if(foeStyle()==4)base+=3;receiveHit(base,kind==2?28:18);}}
  private void receiveHit(int d,float push){if(block&&guard>0){int raw=d;d=Math.max(3,d/4);guard-=raw*1.5f;if(guard<=0){guard=42;stun=1.1f;block=false;fx.sparks(x,312+y,22,Color.rgb(255,222,92));}else fx.sparks(x-facing*28,320+y,8,Color.rgb(190,210,230));}hp-=d;x-=facing*push;hitFlash=.10f;shake=.08f;hitStop=.035f;combo=0;fx.sparks(x+facing*22,317+y,9,Color.rgb(255,145,55));}
  private void superArc(){atk=.62f;pAttack=4;for(int i=0;i<3;i++)shots.add(new Shot(x+facing*(42+i*28),292+y+i*7,facing*(470+i*55),false,16));fx.sparks(x+facing*70,300+y,38,Color.rgb(115,220,255));shake=.25f;tone(27,90);}
  private void nextRoundOrMatch(){if(pWins>=2){matchWins++;score+=1500;ladder++;pWins=eWins=0;if(ladder>=5){owner.reportGameComplete(score);ladder=0;matchWins=0;}restart();return;}if(eWins>=2){owner.reportGameOver(score);pWins=eWins=0;ladder=Math.max(0,ladder-1);restart();return;}round++;restart();}

  @Override void drawGame(Canvas c){float sh=shake>0?(float)Math.sin(System.currentTimeMillis()*.08)*7:0;c.save();c.translate(sh,0);drawStage(c);fighter(c,x,389+y,false,facing,pAttack,atk,block);fighter(c,ex,389+ey,true,eFacing,eAttack,eAtk,enemyBlock>0);drawFoeAccessory(c,ex,389+ey);for(Shot s:shots){fill(c,s.enemy?Color.rgb(190,94,255):Color.rgb(94,203,255),s.x-9,s.y-4,s.x+10,s.y+4);fill(c,Color.WHITE,s.x-3,s.y-2,s.x+4,s.y+2);}fx.draw(c,p);if(hitFlash>0)fill(c,Color.argb(55,255,235,175),0,74,960,410);c.restore();drawHud(c);if(intro>0){fill(c,Color.argb(155,0,0,0),285,155,675,272);text(c,"ROUND "+round,480,203,31,Color.rgb(255,213,84),Paint.Align.CENTER,true);text(c,intro>.65f?"READY":"FIGHT!",480,244,26,Color.WHITE,Paint.Align.CENTER,true);}if(koTimer>0)text(c,"K.O.",480,230,58,Color.rgb(255,212,72),Paint.Align.CENTER,true);
    arcadeButton(c,bL,"◀",Color.rgb(45,99,158),left);arcadeButton(c,bR,"▶",Color.rgb(45,99,158),right);arcadeButton(c,bJ,"▲",Color.rgb(45,99,158),jump);arcadeButton(c,bP,t("ÜT","HIT","HIEB","GOLPE","COUP","拳","COLPO","SOCO","CIOS","SLAG","LOV","УДАР"),Color.rgb(169,58,43),touched(bP));arcadeButton(c,bK,t("RÚG","KICK","TRITT","PATADA","PIED","踢","CALCIO","CHUTE","KOP","TRAP","PICIOR","ПИНОК"),Color.rgb(178,91,35),touched(bK));arcadeButton(c,bB,t("VÉD","BLOCK","BLOCK","BLOQ","BLOC","防御","PARA","DEF","BLOK","BLOK","BLOC","БЛОК"),Color.rgb(54,101,139),block);arcadeButton(c,bA,special>=99?"OVERLOAD":special>=50?"ARC":"…",Color.rgb(119,65,165),touched(bA));}
  private void drawStage(Canvas c){int s=foeStyle();int sky=s==0?Color.rgb(76,42,91):s==1?Color.rgb(38,49,74):s==2?Color.rgb(56,51,47):s==3?Color.rgb(39,27,67):Color.rgb(70,29,28);fill(c,sky,0,0,960,540);for(int yy=82;yy<238;yy+=18)fill(c,shade(sky,(yy/18)%2==0?14:-6),0,yy,960,yy+8);for(int bx=-30;bx<1000;bx+=145){fill(c,Color.rgb(39,34,37),bx,190,bx+76,392);fill(c,Color.rgb(102,70,43),bx+8,205,bx+19,392);fill(c,Color.rgb(13,15,19),bx+29,246,bx+64,392);for(int yy=260;yy<370;yy+=31)fill(c,Color.rgb(205,128,42),bx+37,yy,bx+52,yy+8);}if(s==1){for(int i=0;i<6;i++){float xx=80+i*160;line(c,Color.rgb(180,188,202),5,xx,110,xx+60,180);}}else if(s==2){fill(c,Color.rgb(73,77,82),410,205,550,392);line(c,Color.rgb(200,170,70),9,480,118,480,207);}else if(s>=3){fill(c,Color.rgb(55,35,31),427,284,540,390);fill(c,Color.rgb(232,84,29),446,305,521,365);fill(c,Color.rgb(255,199,57),459,315,508,351);}fill(c,Color.rgb(42,50,58),0,358,960,540);for(int yy=360;yy<540;yy+=23)line(c,Color.rgb(25,31,37),2,0,yy,960,yy);for(int bx=-120;bx<1080;bx+=56)line(c,Color.rgb(67,77,84),2,bx,358,bx+155,540);line(c,Color.rgb(182,135,49),4,0,394,960,394);for(int i=0;i<8;i++){float cx=70+i*120;fill(c,Color.rgb(18,19,23),cx,325,cx+28,356);fill(c,i%2==0?Color.rgb(74,104,143):Color.rgb(143,65,55),cx+5,331,cx+23,353);}}
  private void drawFoeAccessory(Canvas c,float px,float gy){int s=foeStyle();if(s==1){line(c,Color.rgb(201,204,206),5,px-18,gy-85,px+17,gy-110);fill(c,Color.rgb(202,88,38),px+8,gy-118,px+29,gy-97);}else if(s==2){fill(c,Color.rgb(80,86,92),px-31,gy-95,px+31,gy-75);stroke(c,Color.rgb(200,203,205),3,px-31,gy-95,px+31,gy-75);}else if(s==3){line(c,Color.rgb(125,87,188),7,px-25,gy-90,px+25,gy-90);}else if(s==4){fill(c,Color.rgb(208,164,53),px-26,gy-117,px+26,gy-110);}}
  private void drawHud(Canvas c){fill(c,Color.rgb(7,7,11),0,0,960,77);text(c,"METAL FIGHTER '98",480,29,26,Color.rgb(248,211,80),Paint.Align.CENTER,true);text(c,t("LAKATOS SZAKI","METALWORKER","METALLBAUER","HERRERO","MÉTALLIER","金属工","FABBRO","SERRALHEIRO","ŚLUSARZ","METAALBEWERKER","LĂCĂTUȘ","СЛЕСАРЬ"),18,61,13,Color.WHITE,Paint.Align.LEFT,true);text(c,foeName(),942,61,13,Color.WHITE,Paint.Align.RIGHT,true);bar(c,18,9,hp,Color.rgb(57,194,75),false);bar(c,662,9,ehp,foeCol(),true);text(c,"R"+round+"  "+Math.max(0,(int)roundClock)+"  "+pWins+"-"+eWins,480,59,16,Color.WHITE,Paint.Align.CENTER,true);fill(c,Color.rgb(31,30,37),342,9,618,18);fill(c,Color.rgb(112,65,164),344,11,344+272*special/100f,16);text(c,"ARC "+(int)special+"%",480,18,10,Color.rgb(214,190,255),Paint.Align.CENTER,true);fill(c,Color.rgb(35,38,43),18,68,280,74);fill(c,Color.rgb(72,132,196),19,69,19+260*guard/100f,73);fill(c,Color.rgb(35,38,43),680,68,942,74);fill(c,Color.rgb(196,105,63),681,69,681+260*eGuard/100f,73);if(combo>=2)text(c,"COMBO x"+combo,480,101,21,Color.rgb(255,201,63),Paint.Align.CENTER,true);}
  private void bar(Canvas c,float bx,float by,int v,int col,boolean rev){float w=280;fill(c,Color.rgb(40,35,31),bx,by,bx+w,by+19);float f=Math.max(0,v)/100f;if(rev)fill(c,col,bx+w-w*f+2,by+2,bx+w-2,by+17);else fill(c,col,bx+2,by+2,bx+2+(w-4)*f,by+17);stroke(c,Color.rgb(234,220,170),2,bx,by,bx+w,by+19);}
  private void fighter(Canvas c,float px,float gy,boolean enemy,int face,int attack,float timer,boolean def){int state=def?3:timer>0?2:Math.abs(enemy?evx:vx)>40?1:0;float phase=(System.currentTimeMillis()%1000)/1000f;SpriteKit.worker(c,p,px,gy,1.95f,face,state,phase,enemy);if(timer>0){float d=face>=0?1:-1;if(attack==1)fill(c,enemy?Color.rgb(196,145,101):Color.rgb(224,174,113),px+d*18,gy-85,px+d*56,gy-69);else if(attack==2)line(c,Color.rgb(47,49,55),12,px+d*8,gy-36,px+d*61,gy-53);else if(attack>=3){line(c,Color.rgb(94,194,255),12,px+d*32,gy-88,px+d*142,gy-111);line(c,Color.WHITE,3,px+d*36,gy-88,px+d*142,gy-111);}}}
  private void sync(){left=touched(bL);right=touched(bR);jump=touched(bJ);block=touched(bB);}
  @Override void onGameDown(float tx,float ty){sync();if(in(bP,tx,ty))punch=true;if(in(bK,tx,ty))kick=true;if(in(bA,tx,ty))arc=true;}
  @Override void onGameMove(float tx,float ty){sync();}
  @Override void onGameUp(float tx,float ty){sync();}
}
